import{_ as t,o,c as r,a0 as s}from"./chunks/framework.DScjKhBS.js";const m=JSON.parse('{"title":"Workflow & openspdd commands","description":"Closed-loop delivery, golden rules for prompt vs code updates, and the openspdd command set.","frontmatter":{"title":"Workflow & openspdd commands","description":"Closed-loop delivery, golden rules for prompt vs code updates, and the openspdd command set."},"headers":[],"relativePath":"reports/structured-prompt-driven/02-openspdd-and-workflow.md","filePath":"reports/structured-prompt-driven/02-openspdd-and-workflow.md"}'),n={name:"reports/structured-prompt-driven/02-openspdd-and-workflow.md"};function a(d,e,i,p,l,c){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="workflow-openspdd-commands" tabindex="-1">Workflow &amp; openspdd commands <a class="header-anchor" href="#workflow-openspdd-commands" aria-label="Permalink to &quot;Workflow &amp; openspdd commands&quot;">​</a></h1><p>The SPDD workflow puts prompts under the <strong>same discipline as code</strong>: history, review, and quality gates. Automation is provided by <strong><a href="https://github.com/gszhangwei/open-spdd" target="_blank" rel="noreferrer">open-spdd</a></strong> (<code>openspdd</code>), which implements slash-style commands as repeatable CLI steps so artifacts stay <strong>versioned and reviewable</strong> instead of trapped in chat.</p><p>Source: <a href="https://martinfowler.com/articles/structured-prompt-driven/" target="_blank" rel="noreferrer">Structured-Prompt-Driven Development (SPDD)</a>.</p><hr><h2 id="golden-rules-when-things-diverge" tabindex="-1">Golden rules (when things diverge) <a class="header-anchor" href="#golden-rules-when-things-diverge" aria-label="Permalink to &quot;Golden rules (when things diverge)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Move first</th></tr></thead><tbody><tr><td><strong>Logic / behaviour</strong> is wrong</td><td><strong>Update the structured prompt</strong> (lock intent), then regenerate or patch code</td></tr><tr><td><strong>Refactoring</strong> (same observable behaviour)</td><td><strong>Change code</strong>, then <strong>sync</strong> back into the Canvas</td></tr></tbody></table><p>That pairing — <strong>prompt-first for behaviour</strong>, <strong>code-first then sync for structure</strong> — is how the article avoids silent drift between intent and implementation.</p><hr><h2 id="closed-loop-vs-one-way-pipeline" tabindex="-1">Closed loop vs one-way pipeline <a class="header-anchor" href="#closed-loop-vs-one-way-pipeline" aria-label="Permalink to &quot;Closed loop vs one-way pipeline&quot;">​</a></h2><p>In a <strong>one-way</strong> pipeline, requirements become code and later edits happen in code alone; the original spec goes stale.</p><p>In SPDD the loop closes on two scales:</p><ol><li><strong>Within an iteration:</strong> corrections flow <strong>requirements → prompt → code</strong>; refactors flow <strong>code → prompt</strong> via sync so neither side diverges quietly.</li><li><strong>Across iterations:</strong> accumulated prompt assets (domain model, decisions, norms) become the <strong>baseline</strong> for the next change instead of restarting from scratch.</li></ol><hr><h2 id="spdd-vs-plain-spec-driven-development" tabindex="-1">SPDD vs “plain” spec-driven development <a class="header-anchor" href="#spdd-vs-plain-spec-driven-development" aria-label="Permalink to &quot;SPDD vs “plain” spec-driven development&quot;">​</a></h2><p>The article stresses that SPDD and SDD share “write the spec clearly first,” but SPDD adds:</p><ul><li><strong>Maintained prompt artifact</strong> — not generate-once-and-discard.</li><li><strong>From requirements to engineering spec</strong> — approach, structure, norms, safeguards, not only behaviour.</li><li><strong>Sync, not handoff</strong> — prompt and code co-evolve.</li><li><strong>Repeatable team control</strong> — consistent governance; trade-off analysis lives in analysis phases while the Canvas records <strong>outcomes</strong>.</li></ul><hr><h2 id="openspdd-commands-summary" tabindex="-1">openspdd commands (summary) <a class="header-anchor" href="#openspdd-commands-summary" aria-label="Permalink to &quot;openspdd commands (summary)&quot;">​</a></h2><p>Commands reference the article’s table (versions tied to the <strong>open-spdd</strong> repo). Typical roles:</p><table tabindex="0"><thead><tr><th>Command</th><th>Role</th><th>Purpose (high level)</th></tr></thead><tbody><tr><td><code>/spdd-story</code></td><td>Optional</td><td>Split large requirements into INVEST-sized stories</td></tr><tr><td><code>/spdd-analysis</code></td><td>Core</td><td>Domain keywords, targeted code scan, strategic analysis</td></tr><tr><td><code>/spdd-reasons-canvas</code></td><td>Core</td><td>Full REASONS Canvas — executable blueprint down to operations</td></tr><tr><td><code>/spdd-generate</code></td><td>Core</td><td>Generate code task-by-task per Canvas</td></tr><tr><td><code>/spdd-api-test</code></td><td>Optional</td><td>cURL-based API test script from endpoints / ACs</td></tr><tr><td><code>/spdd-prompt-update</code></td><td>Core</td><td>Incremental Canvas updates when <strong>requirements</strong> drive change</td></tr><tr><td><code>/spdd-sync</code></td><td>Core</td><td>Push <strong>code-side</strong> changes back into the Canvas</td></tr></tbody></table><p>Optional commands may be generated locally if missing, e.g. <code>openspdd generate spdd-story</code> — see the upstream README for current behaviour.</p><hr><h2 id="review-focus" tabindex="-1">Review focus <a class="header-anchor" href="#review-focus" aria-label="Permalink to &quot;Review focus&quot;">​</a></h2><p>With this workflow, review shifts toward <strong>checking intent</strong> against the Canvas and safeguards; reusable patterns accumulate as a <strong>prompt library</strong>, supporting <strong>AI-first software delivery (AIFSD)</strong> as described in the article.</p><hr><p><strong>Previous:</strong> <a href="./reports/structured-prompt-driven/01-spdd-and-reasons.html">What SPDD is &amp; the REASONS Canvas</a> · <strong>Next:</strong> <a href="./reports/structured-prompt-driven/03-case-study-billing-engine.html">Case study: billing engine</a></p>',26)])])}const g=t(n,[["render",a]]);export{m as __pageData,g as default};
